function plank(p = {}) { const g = new THREE.Group(), L = p.l || 1.3; g.add(woodBox([L, p.t || .03, p.w || .12], 0, p.tint || '#c9a06e', [L / 2, (p.t || .03) / 2, 0])); return g; }

