  for (let i = 0; i < 7; i++) { const m = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), ringM.clone()); m.rotation.x = -Math.PI / 2; m.position.y = wy + .003; g.add(m); rings.push(m); }
