  for (let i = 0; i < 4; i++) leaf.add(woodBox([.03, door[3] - .06, .185], 1, ['#8a6c4c', '#7d6145', '#93745a', '#806446'][i], [.015, (door[3] - .06) / 2 + .03, -.1 - i * .19]));
